export interface ProjectRecord {
  path: string;
  name: string;
  addedAt: string;
  /** Main model most recently used in this project. */
  lastModel: string | null;
  /** Main-model thinking level most recently used in this project — a
   *  concrete level word or omp's `auto` selector; legacy registries without
   *  the field are normalized to null at parse time. */
  lastThinkingLevel: string | null;
  /** Advisor state most recently used in this project; null defers to omp
   *  config. Legacy registries without the field are normalized to null at
   *  parse time. */
  lastAdvisor: boolean | null;
  /** Advisor model most recently used, including its optional `:level` suffix. */
  lastAdvisorModel: string | null;
  /**
   * Pinned main model for new sessions, as omp's `provider/id` selector
   * (issue #257). Consumed only at spawn; null = no pin, the last-used memory
   * and omp's config decide as before. Legacy registries without the field
   * are normalized to null at parse time.
   */
  defaultModel: string | null;
  /**
   * Pinned advisor model for new sessions, as omp's `model[:level]` selector
   * (issue #257). Consumed only at spawn; null = defer to the last-used
   * advisor model, then omp config's `modelRoles.advisor`. A pin does not
   * force the advisor on — on/off keeps its own chain (issue #174). Legacy
   * registries without the field are normalized to null at parse time.
   */
  defaultAdvisorModel: string | null;
  /**
   * Browser clock (see CONTEXT.md): shows the date and time above this
   * project's browser panes and stamps it onto every pane screenshot — the
   * camera button, element picks, and agent Page.captureScreenshot results.
   * Legacy registries without the field are normalized to false at parse time.
   */
  browserClock: boolean;
  /**
   * This project's reviewer roster for /code-review (issue #738, ADR-0047 as
   * amended): null = unset, so the global roster (then the default reviewer)
   * applies. Legacy registries without the field are normalized to null at
   * parse time; a present value must pass the structural guard or loads as
   * null — the record always survives.
   */
  reviewRoster: ReviewDocument | null;
}

/**
 * A worktree session's dedicated checkout (see CONTEXT.md "Worktree session").
 */
export interface SessionWorktree {
  /** Absolute path of the checkout under omp-ui's worktrees root. */
  path: string;
  /** The branch created for and checked out in this worktree. */
…
}

  // These maps are what keeps old on-disk registries loadable: the guards
  // deliberately accept absent optional fields, so the spread alone cannot
  // guarantee the now-required keys exist. Do not "simplify" them away.
  // (Issue #294 flipped the record types to required-with-null.)
  const projects = projectsValue
    .filter(isProjectRecord)
    .map((p) => ({
      ...p,
      lastModel: p.lastModel ?? null,
      lastThinkingLevel: p.lastThinkingLevel ?? null,
      lastAdvisor: p.lastAdvisor ?? null,
      lastAdvisorModel: p.lastAdvisorModel ?? null,
      defaultModel: p.defaultModel ?? null,
      defaultAdvisorModel: p.defaultAdvisorModel ?? null,
      browserClock: p.browserClock === true,
      // Never a validity gate (the proposedPlans rule): a malformed roster
      // normalizes to null here so the record always survives.
      reviewRoster: isReviewDocument(p.reviewRoster) ? p.reviewRoster : null,
    }));
  const sessions = sessionsValue
    .filter(isOwnedSessionRecord)
    .map((s) => ({
      ...s,
      advisor: s.advisor === true,
      model: s.model ?? null,
      thinkingLevel: s.thinkingLevel ?? null,
      advisorModel: s.advisorModel ?? null,
      compactionMethod: s.compactionMethod ?? null,
      approvalMode: s.approvalMode ?? null,
      serviceTier: s.serviceTier ?? null,
      subagentModels: s.subagentModels ?? null,
      agentMode: s.agentMode ?? "build",
      worktree: s.worktree
        ? { path: s.worktree.path, branch: s.worktree.branch, base: s.worktree.base ?? null }
        : null,
…
    }));
